+
+        final var indexingThreadsByTier = Map.of(
+            DataTier.DATA_HOT,
+            randomDoubleBetween(4.0, 16.0, true),
+            DataTier.DATA_WARM,
+            1.0,
+            DataTier.DATA_COLD,
+            1.0
