+
+            final var nodeId = Strings.format("node-%s-%03d", tierRole.roleNameAbbreviation(), nodeIndex);
+            discoveryNodesBuilder.add(
+                new DiscoveryNode(
+                    nodeId,
+                    nodeId,
+                    buildNewFakeTransportAddress(),
+                    Map.of("fake_tier", tierRole.roleName()),
+                    Set.of(tierRole),
+                    Version.CURRENT
