+                byteBuffer.putFloat(docVector[i]);
+            }
+
+            byteBuffer.putFloat(docMagnitude);
+            this.docVector = new BytesRef(byteBuffer.array());
+        }
+    }
+
+    private abstract static class KnnByteBenchmarkFunction extends BenchmarkFunction {
