+    private <T> List<T> inherit(Supplier<List<T>> parent, List<T> child) {
+        List<T> combinedList = new ArrayList<>();
+        if (this.parent != null) {
+            combinedList.addAll(parent.get());
+        }
+        combinedList.addAll(child);
