+        final var token1 = (JwtAuthenticationToken) jwtRealm.token(threadContext1);
+        final String principal1 = Strings.format("%s/%s/%s/%s", iss, aud, sub, sub);
+        assertJwtToken(token1, principal1, sharedSecret, signedJWT1);
