+    private List<JwtRealm> getJwtRealms() {
+        final Realms realms = getInstanceFromNode(Realms.class);
+        final List<JwtRealm> jwtRealms = realms.getActiveRealms()
+            .stream()
+            .filter(realm -> realm instanceof JwtRealm)
+            .map(JwtRealm.class::cast)
+            .toList();
+        return jwtRealms;
+    }
