+        return switch (str.toLowerCase(Locale.ROOT)) {
+            case "fail" -> FAIL;
+            case "continue" -> CONTINUE;
+            default -> throw new IllegalArgumentException("Unknown onScriptError [" + str + "]");
+        };
+    }
