+        } else if (relation == GeoRelation.QUERY_CONTAINS) {
+            this.relation = GeoRelation.QUERY_CROSSES;
+        }
+    }
+
+    private boolean canBeContained() {
+        return this.relation == null || this.relation == GeoRelation.QUERY_CONTAINS;
